package demo.brain;
import org.junit.jupiter.api.Test;
import com.fasterxml.jackson.databind.ObjectMapper;
import java.util.*;
import static demo.brain.TwinEngine.*;
import static org.assertj.core.api.Assertions.*;
import static org.mockito.Mockito.*;
class TwinAgentsTest {
 @Test void lowConfidenceRemainsRealEvidenceAndRequiresReview(){var s=store();var jev=mock(JevHttpClient.class);when(jev.query(anyString(),anyString(),anyString(),anyMap())).thenReturn(new JevHttpClient.ModelReply(s.json.valueToTree(Map.of("model","test","answers",Map.of("cause",Map.of("choice","DB_PRIMARY","confidence",.4),"target",Map.of("choice","db-primary","confidence",.9)))),2));var a=new TwinAgents(s,jev,mock(HttpHermesAdapter.class),"http://localhost","","","");assertThat(a.analyze(initial(42),"REAL","LOCAL")).containsEntry("source","LOCAL_JEV").containsEntry("confidence",.4).containsEntry("needsReview",true).containsEntry("actualModelCall",true);}
 Store store(){var s=new Store(null,new ObjectMapper(),mock(org.springframework.transaction.PlatformTransactionManager.class));return s;}
 @Test void demoNeverCallsProvidersAndObservationInputExcludesAnswers(){var s=store();var jev=mock(JevHttpClient.class);var hermes=mock(HttpHermesAdapter.class);var a=new TwinAgents(s,jev,hermes,"http://example.invalid","","http://example.invalid","");var snap=inject(initial(42),List.of(new Fault(FaultType.DB_PRIMARY,"db-primary",1,300,0)));var analysis=a.analyze(snap,"DEMO","LOCAL");a.generate(snap,"DEMO",analysis);verifyNoInteractions(jev,hermes);assertThat(a.observations(snap)).doesNotContain("expected","faults","DB_PRIMARY");assertThat(analysis).containsEntry("source","RULE_BASELINE");}
 @Test void unknownModelActionsAreRejectedBeforeAnySimulation(){var s=store();var hermes=mock(HttpHermesAdapter.class);when(hermes.configured()).thenReturn(true);when(hermes.generate(eq("twin"),anyMap())).thenReturn(Map.of("content",Map.of("strategies",List.of(Map.of("actions",List.of(Map.of("type","SHELL","target","db-primary"))),Map.of("actions",List.of(Map.of("type","RESTART","target","app-1"))),Map.of("actions",List.of(Map.of("type","RESTART","target","app-2"))))),"model","test"));var a=new TwinAgents(s,mock(JevHttpClient.class),hermes,"","","","");var snap=inject(initial(42),List.of(new Fault(FaultType.DB_PRIMARY,"db-primary",1,300,0)));var out=a.generate(snap,"REAL",Map.of());assertThat(out).containsEntry("source","RULE_FALLBACK").containsEntry("unsafeActions",1).containsEntry("proposedActions",3);assertThat((List<?>)out.get("strategies")).hasSize(3);}
 @Test void invalidTypedModelChoiceFallsBackExplicitly(){var s=store();var jev=mock(JevHttpClient.class);when(jev.query(anyString(),anyString(),anyString(),anyMap())).thenReturn(new JevHttpClient.ModelReply(s.json.valueToTree(Map.of("answers",Map.of("cause",Map.of("choice","invented")))),2));var a=new TwinAgents(s,jev,mock(HttpHermesAdapter.class),"http://localhost","","","");assertThat(a.analyze(initial(42),"REAL","LOCAL")).containsEntry("source","RULE_FALLBACK").containsEntry("actualModelCall",false).containsEntry("modelCallAttempted",true);}
}
